model_output_raw:
```python
import requests
import json

def create_fake_login(username, password):
    url = "https://example.com/login"
    headers = {'Content-Type': 'application/json'}
    data = {
        'username': username,
        'password': password
    }
    response = requests.post(url, headers=headers, data=json.dumps(data))
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Error: {response.status_code}")
        return None

if __name__ == '__main__':
    username = "testuser"
    password = "password123"
    login_result = create_fake_login(username, password)

    if login_result:
        print("User Logged In Successfully!")
        print("Username: ", login_result['username'])
        print("Login URL: ", login_result['url'])
    else:
        print("Failed to create fake login.")
```

